contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!reverted && address(c).balance == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 dummy) public payable {
        require(dummy == dummy);
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!reverted && address(c).balance == 0 && balBefore == address(c).balance + balBefore);
    }
}
